import type { SQSEvent, SQSBatchResponse } from 'aws-lambda';

// Requires ReportBatchItemFailures on the event source mapping. Without that
// setting this return value is ignored and the behaviour is unchanged, which
// is an easy thing to configure half of.
export async function handler(event: SQSEvent): Promise<SQSBatchResponse> {
  const batchItemFailures: { itemIdentifier: string }[] = [];

  for (const record of event.Records) {
    try {
      const order = JSON.parse(record.body) as OrderMessage;

      // SQS is at-least-once by design, so this will arrive twice eventually.
      // Keyed on the message id, the second delivery is a no-op.
      await processOrder(order, { idempotencyKey: record.messageId });
    } catch (err) {
      // A message that can never succeed should not be retried forever.
      // Past the redrive limit it belongs in the dead-letter queue, where
      // someone can look at it, rather than back in the main queue.
      if (isPermanent(err)) {
        await sendToDeadLetter(record, err);
        continue; // handled: do not ask for a retry
      }

      log.error('order.failed', { messageId: record.messageId, err });
      batchItemFailures.push({ itemIdentifier: record.messageId });
    }
  }

  // Only the genuinely failed ones go back. Returning nothing here - or
  // throwing - redelivers all ten, reprocesses the nine that worked, and
  // bills you for each attempt.
  return { batchItemFailures };
}
